from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse,parse_qs
import json, sqlite3
DB='/workspace/audit-target.sqlite'
con=sqlite3.connect(DB); con.execute('CREATE TABLE IF NOT EXISTS people (id INTEGER, name TEXT, role TEXT)'); con.execute('DELETE FROM people'); con.executemany('INSERT INTO people VALUES (?,?,?)',[(1,'Mira','analyst'),(2,'Noah','operator'),(3,'Isha','researcher')]); con.commit(); con.close()
RECORDS={1001:{'id':1001,'owner':'fictional-user-a','memo':'Demo schedule'},1002:{'id':1002,'owner':'fictional-user-b','memo':'Demo contact list'}}
class Handler(BaseHTTPRequestHandler):
 def do_GET(self):
  p=urlparse(self.path)
  if p.path=='/health': body=b'{"service":"audit-demo","status":"ready"}'; self.send_response(200)
  elif p.path=='/search':
   q=parse_qs(p.query).get('q',[''])[0]; con=sqlite3.connect(DB)
   try: rows=con.execute("SELECT id,name,role FROM people WHERE name LIKE '%"+q+"%'").fetchall(); body=json.dumps({'results':[{'id':r[0],'name':r[1],'role':r[2]} for r in rows]}).encode(); self.send_response(200)
   except Exception: body=b'{"error":"query failed"}'; self.send_response(400)
   finally: con.close()
  elif p.path=='/record':
   try: record=RECORDS[int(parse_qs(p.query).get('id',['0'])[0])]; body=json.dumps(record).encode(); self.send_response(200)
   except Exception: body=b'{"error":"not found"}'; self.send_response(404)
  else: body=b'{"error":"not found"}'; self.send_response(404)
  self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
 def log_message(self,*a): pass
HTTPServer(('127.0.0.1',8080),Handler).serve_forever()
